mapper.select:
SELECT cr.instance_id AS instanceId, cr.cmd_seq AS cmdSeq, ci.down_cmd AS downCmd, cr.translated_cmd_content AS translatedCmdContent, cr.single_cmd_status AS singleCmdStatus, cr.start_time AS startTime, cr.end_time AS endTime, cr.device_id AS deviceId FROM iot_command_record cr INNER JOIN iot_command_info ci ON cr.cmd_seq = ci.cmd_seq WHERE cr.deleted = 0 AND ci.deleted = 0
AND cr.device_id = #{param.deviceId}
AND cr.device_id IN ( SELECT id FROM iot_dev_device WHERE deleted = 0 AND (device_number LIKE CONCAT('%', #{param.deviceNameOrNumber}, '%') OR name LIKE CONCAT('%', #{param.deviceNameOrNumber}, '%')) )
AND ci.down_cmd = #{param.downCmd}
AND cr.target_identifier = #{param.targetIdentifier}
AND cr.single_cmd_status = #{param.singleCmdStatus}
AND cr.start_time >= #{param.startTime}
AND cr.start_time <= #{param.endTime}
ORDER BY cr.create_time DESC
